import Cocoa
import Accelerate


private func generateHistogram(cgImage: CGImage) -> ([[vImagePixelCount]], Int)? {
    var sourceBuffer = vImage_Buffer()
    defer {
        free(sourceBuffer.data)
    }

    var cgImageFormat = vImage_CGImageFormat(
        bitsPerComponent: UInt32(cgImage.bitsPerComponent),
        bitsPerPixel: UInt32(cgImage.bitsPerPixel),
        colorSpace: Unmanaged.passUnretained(cgImage.colorSpace!),
        bitmapInfo: cgImage.bitmapInfo,
        version: 0,
        decode: nil,
        renderingIntent: .defaultIntent
    )

    let noFlags = vImage_Flags(kvImageNoFlags)
    var error = vImageBuffer_InitWithCGImage(&sourceBuffer, &cgImageFormat, nil, cgImage, noFlags)
    assert(error == kvImageNoError)

    if cgImage.alphaInfo == .premultipliedLast {
        error = vImageUnpremultiplyData_RGBA8888(&sourceBuffer, &sourceBuffer, noFlags)
    } else if cgImage.alphaInfo == .premultipliedFirst {
        error = vImageUnpremultiplyData_ARGB8888(&sourceBuffer, &sourceBuffer, noFlags)
    }
    assert(error == kvImageNoError)

    let histogramBins = (0...3).map { _ in
        return [vImagePixelCount](repeating: 0, count: 256)
    }
    var mutableHistogram: [UnsafeMutablePointer<vImagePixelCount>?] = histogramBins.map {
        return UnsafeMutablePointer<vImagePixelCount>(mutating: $0)
    }
    error = vImageHistogramCalculation_ARGB8888(&sourceBuffer, &mutableHistogram, noFlags)
    assert(error == kvImageNoError)

    let alphaBinIndex = [.last, .premultipliedLast].contains(cgImage.alphaInfo) ? 3 : 0
    return (histogramBins, alphaBinIndex)
}

func imageHasTransparency(_ cgImage: CGImage) -> Bool {
    guard cgImage.bitsPerComponent == 8, cgImage.bitsPerPixel == 32 else {
        return false
    }
    guard [.first, .last, .premultipliedFirst, .premultipliedLast].contains(cgImage.alphaInfo) else {
        return false
    }
    if let (histogramBins, alphaBinIndex) = generateHistogram(cgImage: cgImage) {
        for i in 0 ..< 255 {
            if histogramBins[alphaBinIndex][i] > 0 {
                return true
            }
        }
    }
    return false
}

private func scaledDrawingContext(_ cgImage: CGImage, maxSize: CGSize) -> DrawingContext {
    var size = CGSize(width: cgImage.width, height: cgImage.height)
    if (size.width > maxSize.width && size.height > maxSize.height) {
        size = size.aspectFilled(maxSize)
    }
    let context = DrawingContext(size: size, scale: 1.0, clear: true)
    context.withFlippedContext { context in
        context.draw(cgImage, in: CGRect(origin: CGPoint(), size: size))
    }
    return context
}

public func imageRequiresInversion(_ cgImage: CGImage) -> Bool {
    guard cgImage.bitsPerComponent == 8, cgImage.bitsPerPixel == 32 else {
        return false
    }
    guard [.first, .last, .premultipliedFirst, .premultipliedLast].contains(cgImage.alphaInfo) else {
        return false
    }

    let context = scaledDrawingContext(cgImage, maxSize: CGSize(width: 128.0, height: 128.0))
    if let cgImage = context.generateImage(), let (histogramBins, alphaBinIndex) = generateHistogram(cgImage: cgImage) {
        var hasAlpha = false
        for i in 0 ..< 255 {
            if histogramBins[alphaBinIndex][i] > 0 {
                hasAlpha = true
                break
            }
        }

        if hasAlpha {
            var matching: Int = 0
            var total: Int = 0
            for y in 0 ..< Int(context.size.height) {
                for x in 0 ..< Int(context.size.width) {
                    var saturation: CGFloat = 0.0
                    var brightness: CGFloat = 0.0
                    var alpha: CGFloat = 0.0
                    context.colorAt(CGPoint(x: x, y: y)).getHue(nil, saturation: &saturation, brightness: &brightness, alpha: &alpha)
                    if alpha < 1.0 {
                        hasAlpha = true
                    }

                    if alpha > 0.0 {
                        total += 1
                        if saturation < 0.1 && brightness < 0.25 {
                            matching += 1
                        }
                    }
                }
            }
            return CGFloat(matching) / CGFloat(total) > 0.85
        }
    }
    return false
}


import Cocoa

private func supportsImageAlphaAnalysis(_ image: CGImage) -> Bool {
    guard image.bitsPerComponent == 8, image.bitsPerPixel == 32 else { return false }
    switch image.alphaInfo {
    case .first, .last, .premultipliedFirst, .premultipliedLast:
        return true
    default:
        return false
    }
}

private func imageAnalysisContext(_ image: CGImage, size: CGSize) -> CGContext? {
    guard size.width.isFinite, size.height.isFinite, size.width > 0, size.height > 0, size.width < CGFloat(Int.max), size.height < CGFloat(Int.max) else { return nil }
    let width = max(1, Int(size.width)), height = max(1, Int(size.height))
    let (bytesPerRow, rowOverflow) = width.multipliedReportingOverflow(by: 4)
    let (_, sizeOverflow) = bytesPerRow.multipliedReportingOverflow(by: height)
    guard !rowOverflow, !sizeOverflow else { return nil }
    let bitmapInfo = CGBitmapInfo.byteOrder32Little.rawValue | CGImageAlphaInfo.premultipliedFirst.rawValue
    guard let context = CGContext(data: nil, width: width, height: height, bitsPerComponent: 8, bytesPerRow: bytesPerRow, space: deviceColorSpace, bitmapInfo: bitmapInfo) else { return nil }
    context.clear(CGRect(x: 0, y: 0, width: width, height: height))
    context.draw(image, in: CGRect(origin: .zero, size: size))
    return context
}

func imageHasTransparency(_ image: CGImage) -> Bool {
    guard supportsImageAlphaAnalysis(image), let context = imageAnalysisContext(image, size: CGSize(width: image.width, height: image.height)), let data = context.data else { return false }
    return withExtendedLifetime(context) {
        for y in 0..<context.height {
            let row = data.advanced(by: y * context.bytesPerRow).assumingMemoryBound(to: UInt32.self)
            for x in 0..<context.width {
                if UInt32(littleEndian: row[x]) >> 24 < 255 { return true }
            }
        }
        return false
    }
}

public func imageRequiresInversion(_ image: CGImage) -> Bool {
    guard supportsImageAlphaAnalysis(image) else { return false }
    var size = CGSize(width: image.width, height: image.height)
    let maximumSize = CGSize(width: 128, height: 128)
    if size.width > maximumSize.width && size.height > maximumSize.height {
        size = size.aspectFilled(maximumSize)
    }
    guard let context = imageAnalysisContext(image, size: size), let data = context.data else { return false }
    return withExtendedLifetime(context) {
        var hasTransparency = false
        var matching = 0
        var total = 0
        for y in 0..<context.height {
            let row = data.advanced(by: y * context.bytesPerRow).assumingMemoryBound(to: UInt32.self)
            for x in 0..<context.width {
                let pixel = UInt32(littleEndian: row[x])
                let alpha = Int(pixel >> 24)
                if alpha < 255 { hasTransparency = true }
                if alpha == 0 { continue }
                total += 1
                let red = Int((pixel >> 16) & 255)
                let green = Int((pixel >> 8) & 255)
                let blue = Int(pixel & 255)
                let maximum = max(red, max(green, blue))
                if maximum * 4 < alpha {
                    let minimum = min(red, min(green, blue))
                    if maximum == 0 || (maximum - minimum) * 10 < maximum {
                        matching += 1
                    }
                }
            }
        }
        return hasTransparency && total > 0 && Double(matching) / Double(total) > 0.85
    }
}
